    double heldLeft,heldRight,inputLevel,noiseLowLeft,noiseLowRight,signalPhase,signalStart,signalRatio,crushPhase,texturePhase,radioLowLeft,radioLowRight,radioHighLeft,radioHighRight;
    uint noiseState=374761393;
