    double Noise(){noiseState^=noiseState<<13;noiseState^=noiseState>>17;noiseState^=noiseState<<5;return noiseState/(double)UInt32.MaxValue*2-1;}
    public void Clear(){Array.Clear(historyLeft,0,historyLeft.Length);Array.Clear(historyRight,0,historyRight.Length);position=recorded=grainCountdown=grainIndex=0;ResetGlitch();foreach(Grain grain in grains)grain.Length=0;}
