    public void Process(ref double left,ref double right,double glitchMix,double fragmentsMix,GlitchType type=GlitchType.Stutter,double glitchVolume=1,double noteFrequency=220){
      historyLeft[position]=left;historyRight[position]=right;if(recorded<historyLeft.Length)recorded++;
      if(fragmentsMix>.00001&&recorded>22050){
        if(--grainCountdown<=0){Grain grain=grains[grainIndex];grainIndex=(grainIndex+1)%grains.Length;grain.Position=position-11025-random.Next(8820);grain.Length=4410+random.Next(4410);grain.Age=0;grain.Speed=speeds[random.Next(speeds.Length)];grain.Swap=random.Next(2)==0;grainCountdown=2205+random.Next(1103);}
