        if(glitchPhase==0){glitchPeriod=8820+random.Next(6615);glitchDuration=type==GlitchType.Stutter?glitchPeriod*3/5:type==GlitchType.Radio||type==GlitchType.Modem?glitchPeriod*4/5:441+random.Next(1323);sliceLength=882+random.Next(1544);sliceStart=position-sliceLength;holdCounter=0;signalStart=350+random.Next(1800);signalRatio=random.Next(2)==0?.25:2.5;signalPhase=0;}
