            Mix(ref left,ref right,artifactLeft*inputLevel,artifactRight*inputLevel,wet,glitchVolume,.65);
          }
        }
        if(++glitchPhase>=glitchPeriod)glitchPhase=0;
      }else if(glitchMix<=.00001||glitchVolume<=1e-7)glitchPhase=0;
