    const int Frames=512,Count=4; IntPtr handle; readonly IntPtr[] headers=new IntPtr[Count],buffers=new IntPtr[Count]; readonly bool[] prepared=new bool[Count]; readonly Synth synth; readonly SoundBoxes boxes; readonly TCKAudio.PcmRecorder recorder;
