    public AudioOutput(Synth s,uint device,TCKAudio.PcmRecorder takeRecorder=null,SoundBoxes soundBoxes=null){synth=s;boxes=soundBoxes;recorder=takeRecorder;Native.Format f=new Native.Format{tag=1,channels=2,rate=Synth.Rate,bytes=Synth.Rate*4,align=4,bits=16,extra=0};uint e=Native.waveOutOpen(out handle,device,ref f,IntPtr.Zero,UIntPtr.Zero,0);if(e!=0)throw new Exception("Audio open error "+e+". Choose another output or retry.");try{for(int i=0;i<Count;i++){buffers[i]=Marshal.AllocHGlobal(Frames*4);headers[i]=Marshal.AllocHGlobal(Marshal.SizeOf(typeof(Native.Header)));Native.Header h=new Native.Header{data=buffers[i],length=Frames*4};Marshal.StructureToPtr(h,headers[i],false);e=Native.waveOutPrepareHeader(handle,headers[i],(uint)Marshal.SizeOf(typeof(Native.Header)));if(e!=0)throw new Exception("Audio prepare error "+e);prepared[i]=true;}running=true;worker=new Thread(Loop);worker.IsBackground=true;worker.Priority=ThreadPriority.AboveNormal;worker.Start();}catch{Dispose();throw;}}
