      bool tiny=Height<78,dense=Height<110,compact=Height<140;using(Font f=Theme.Font(dense?9:11,FontStyle.Bold))using(Brush b=new SolidBrush(Theme.Text))g.DrawString(Title,f,b,14,dense?6:12);
