      int diameter=dense?(tiny?22:34):compact?48:64;Rectangle arc=new Rectangle(17,tiny?26:dense?31:compact?44:49,diameter,diameter);using(Pen p=new Pen(Color.FromArgb(63,72,75),dense?4:6)){p.StartCap=p.EndCap=LineCap.Round;g.DrawArc(p,arc,135,270);}using(Pen p=new Pen(Theme.Copper,dense?4:6)){p.StartCap=p.EndCap=LineCap.Round;g.DrawArc(p,arc,135,(float)(270*Math.Max(.002,Value)));}
      double angle=(135+270*Value)*Math.PI/180;float centerX=arc.X+arc.Width/2f,centerY=arc.Y+arc.Height/2f,radius=dense?9:compact?13:18;int inset=dense?6:9;using(Brush b=new SolidBrush(Color.FromArgb(47,54,56)))g.FillEllipse(b,arc.X+inset,arc.Y+inset,arc.Width-inset*2,arc.Height-inset*2);using(Pen p=new Pen(Theme.Text,dense?2:3))g.DrawLine(p,centerX,centerY,centerX+(float)(radius*Math.Cos(angle)),centerY+(float)(radius*Math.Sin(angle)));
      using(Font f=new Font("Consolas",tiny?14:dense?16:20,FontStyle.Bold))using(Brush b=new SolidBrush(Theme.Text))g.DrawString(Math.Round(Value*100).ToString("00"),f,b,dense?75:100,tiny?24:dense?28:compact?46:56);
      if(!tiny)using(Font f=Theme.Font(dense?7:8,FontStyle.Regular))using(Brush b=new SolidBrush(Theme.Dim)){g.DrawString(Hint,f,b,dense?75:100,dense?54:compact?76:86);g.DrawString(Mapping,f,b,14,Height-(dense?15:18));}
      if(Focused)using(Pen p=new Pen(Theme.Mint))g.DrawRectangle(p,5,5,Width-11,Height-11);
    }
    public void SetValue(double v,bool notify){Value=Math.Max(0,Math.Min(1,v));Invalidate();if(notify&&Changed!=null)Changed(Value);}
