    void FinishTake(){try{string path=recorder.Stop();if(path!=null){lastTake=path;takeStatus.Text="Saved "+Path.GetFileName(path)+" · ready for TCK03.";}}catch(Exception error){takeStatus.Text=error.Message;if(!IsDisposed)MessageBox.Show(this,error.Message,"Recording ended");}finally{takeOpen=false;recordTake.Text="● RECORD";playTake.Enabled=exportTake.Enabled=sendTake.Enabled=lastTake!=null&&File.Exists(lastTake);}}
    void FitToScreen(){Rectangle area=Screen.FromControl(this).WorkingArea;if(Width>area.Width||Height>area.Height){MinimumSize=new Size(Math.Min(MinimumSize.Width,area.Width),Math.Min(MinimumSize.Height,area.Height));Size=new Size(Math.Min(Width,area.Width),Math.Min(Height,area.Height));Location=new Point(Math.Max(area.Left,Math.Min(Left,area.Right-Width)),Math.Max(area.Top,Math.Min(Top,area.Bottom-Height)));}}
