    string sessionOverride;
    string SessionPath{get{return sessionOverride??Path.Combine(SynthHome.Folder,"sound-session.txt");}}
    void SaveSession(){try{List<string> values=new List<string>();values.Add("preset="+presets.SelectedIndex);for(int index=0;index<8;index++)values.Add("dial"+index+"="+(int)Math.Round(dials[index].Value*10000));values.Add("octave="+octave);values.Add("bloom="+bloomControl.Value);values.Add("echo="+echoTimeControl.Value);values.Add("glitch="+(glitchToggle.Checked?1:0));values.Add("fragments="+(fragmentsToggle.Checked?1:0));values.Add("glitchStrength="+glitchControl.Value);values.Add("fragmentsStrength="+fragmentsControl.Value);values.Add("glitchType="+glitchTypeChoice.SelectedIndex);values.Add("glitchVolume="+glitchVolumeControl.Value);values.Add("master="+volume.Value);values.Add("pitch="+Engine.PitchSemitones);values.Add("clarity="+(clarityToggle.Checked?1:0));values.Add("boxGlitchType="+boxGlitchChoice.SelectedIndex);values.Add("boxElectro="+electroChoice.SelectedIndex);values.Add("boxGlitchVolume="+boxGlitchLevel.Value);values.Add("boxElectroVolume="+electroLevel.Value);values.Add("boxGlitchNote="+(int)boxGlitchNote.Value);values.Add("boxElectroNote="+(int)electroNote.Value);values.Add("technology="+technologyChoice.SelectedIndex);values.Add("technologyKeyboard="+(Engine.TechnologyType>=0?1:0));values.Add("technologyCharacter="+technologyCharacter.Value);values.Add("technologyVolume="+technologyLevel.Value);values.Add("audioOutput="+audioChoice.Text);Rack.SaveLayers(values);File.WriteAllLines(SessionPath,values.ToArray());}catch{activity.Text="Sound works now; unable to save this session.";}}
    static int SessionValue(Dictionary<string,int> values,string name,int fallback,int minimum,int maximum){int value;return values.TryGetValue(name,out value)?Math.Max(minimum,Math.Min(maximum,value)):fallback;}
    void LoadSession(){loadingLayers=true;try{if(!File.Exists(SessionPath))return;string outputLine=Array.Find(File.ReadAllLines(SessionPath),line=>line.StartsWith("audioOutput="));if(outputLine!=null){int outputIndex=audioChoice.Items.IndexOf(outputLine.Substring(12));if(outputIndex>=0&&audioChoice.SelectedIndex!=outputIndex)audioChoice.SelectedIndex=outputIndex;}Dictionary<string,int> values=new Dictionary<string,int>();foreach(string line in File.ReadAllLines(SessionPath)){string[] parts=line.Split('=');int value;if(parts.Length==2&&int.TryParse(parts[1],out value))values[parts[0]]=value;}technologyChoice.SelectedIndex=SessionValue(values,"technology",0,0,11);technologyCharacter.Value=SessionValue(values,"technologyCharacter",50,0,100);technologyLevel.Value=SessionValue(values,"technologyVolume",35,0,100);int restoredPreset=SessionValue(values,"preset",0,0,Patch.All.Length-1);presets.SelectedIndex=restoredPreset<11?restoredPreset:0;Rack.ResetLayers(presets.SelectedIndex);if(SessionValue(values,"technologyKeyboard",0,0,1)==1)Engine.SelectTechnology(technologyChoice.SelectedIndex);for(int index=0;index<8;index++)dials[index].SetValue(SessionValue(values,"dial"+index,(int)Math.Round(Engine.Get(index)*10000),0,10000)/10000.0,true);octave=SessionValue(values,"octave",4,1,7);piano.BaseNote=octave*12;piano.Invalidate();bloomControl.Value=SessionValue(values,"bloom",bloomControl.Value,0,100);echoTimeControl.Value=SessionValue(values,"echo",echoTimeControl.Value,80,4000);glitchControl.Value=SessionValue(values,"glitchStrength",65,0,100);fragmentsControl.Value=SessionValue(values,"fragmentsStrength",65,0,100);glitchTypeChoice.SelectedIndex=SessionValue(values,"glitchType",0,0,glitchTypes.Length-1);glitchVolumeControl.Value=SessionValue(values,"glitchVolume",200,0,400);volume.Value=SessionValue(values,"master",20,0,80);Engine.Volume(volume.Value/100.0);SetPitch(SessionValue(values,"pitch",0,-12,12));clarityToggle.Checked=SessionValue(values,"clarity",1,0,1)==1;Engine.SetHold(false);Engine.SetDrone(Patch.All[presets.SelectedIndex].Drone);glitchToggle.Checked=SessionValue(values,"glitch",0,0,1)==1;fragmentsToggle.Checked=SessionValue(values,"fragments",0,0,1)==1;boxGlitchChoice.SelectedIndex=SessionValue(values,"boxGlitchType",6,0,6);electroChoice.SelectedIndex=SessionValue(values,"boxElectro",1,0,7);boxGlitchLevel.Value=glitchControl.Value;electroLevel.Value=SessionValue(values,"boxElectroVolume",35,0,100);boxGlitchNote.Value=SessionValue(values,"boxGlitchNote",60,24,96);electroNote.Value=SessionValue(values,"boxElectroNote",60,24,96);Rack.RestoreLayers(File.ReadAllLines(SessionPath));boxes.Master=volume.Value/100.0;UpdateHold();activity.Text="Sound restored · drone sounds latch on a tap. Sources start silent until you play.";}catch{activity.Text="Could not restore saved sound; controls remain available.";}finally{loadingLayers=false;RefreshLayers();}}
    Label LabelAt(string t,int x,int y,int w,int h,float size,Color color){return new Label{Text=t,Bounds=new Rectangle(x,y,w,h),Font=Theme.Font(size,FontStyle.Regular),ForeColor=color};}
    static void StyleCombo(ComboBox c){c.DropDownStyle=ComboBoxStyle.DropDownList;c.FlatStyle=FlatStyle.Flat;c.BackColor=Theme.Card;c.ForeColor=Theme.Text;c.Font=Theme.Font(11,FontStyle.Regular);c.Dock=DockStyle.Fill;c.Margin=new Padding(0,4,12,4);c.DrawMode=DrawMode.OwnerDrawFixed;c.ItemHeight=24;c.DrawItem+=delegate(object sender,DrawItemEventArgs e){using(Brush bg=new SolidBrush((e.State&DrawItemState.Selected)!=0?Color.FromArgb(55,68,66):Theme.Card))e.Graphics.FillRectangle(bg,e.Bounds);if(e.Index>=0)using(Brush fg=new SolidBrush(Theme.Text))e.Graphics.DrawString(c.Items[e.Index].ToString(),c.Font,fg,e.Bounds.X+7,e.Bounds.Y+3);};}
