    static Button MakeButton(string text,Color color){Button b=new Button{Text=text,Dock=DockStyle.Fill,Margin=new Padding(0,4,0,4)};StyleButton(b,color);return b;}
    void StartAudio(){if(takeOpen)FinishTake();Panic();audioFailure=null;if(audio!=null){audio.Dispose();audio=null;}try{uint device=audioChoice.SelectedIndex<=0?uint.MaxValue:(uint)(audioChoice.SelectedIndex-1);audio=new AudioOutput(Engine,device,recorder,boxes);audioStatus.Text="Audio ready · 44.1 kHz stereo";}catch(Exception ex){audioFailure=ex.Message;audioStatus.Text="AUDIO OFFLINE · check Sound settings";activity.Text=ex.Message;}}
    void RefreshAudio(){string previous=audioChoice.Text;updating=true;audioChoice.Items.Clear();audioChoice.Items.AddRange(Native.AudioNames());int index=audioChoice.Items.IndexOf(previous);audioChoice.SelectedIndex=index>=0?index:0;updating=false;StartAudio();}
    void RefreshMidi(bool force){string[] names=Native.MidiNames();if(!force&&String.Join("|",names)==String.Join("|",midiNames))return;string previous=midi.Name;midi.Dispose();Engine.Panic();midiNames=names;updating=true;midiChoice.Items.Clear();midiChoice.Items.Add("Computer / on-screen keyboard only");midiChoice.Items.AddRange(names);int selected=0;for(int i=0;i<names.Length;i++)if(names[i]==previous)selected=i+1;if(selected==0)for(int i=0;i<names.Length;i++)if(names[i].ToLowerInvariant().Contains("mpk")||names[i].ToLowerInvariant().Contains("akai")){selected=i+1;break;}midiChoice.SelectedIndex=selected;updating=false;ConnectMidi();}
    void ConnectMidi(){midi.Dispose();Engine.Panic();if(midiChoice.SelectedIndex<=0){midiStatus.Text=midiNames.Length==0?"No USB MIDI detected · fallback ready":"MIDI disconnected · fallback ready";return;}try{int i=midiChoice.SelectedIndex-1;midi.Open(i,midiNames[i]);midiStatus.Text="CONNECTED · "+midi.Name;}catch(Exception ex){midiStatus.Text="MIDI OFFLINE · fallback ready";activity.Text=ex.Message;}}
    void Tick(object sender,EventArgs args){int data,n=0;if(midi.Overflow){while(midi.Pop(out data)){}Panic();midi.Overflow=false;activity.Text="MIDI overload cleared.";}while(n++<512&&midi.Pop(out data))Router.Handle(data);if(Router.Learn<0&&mapDirty){SaveMaps();mapDirty=false;}UpdateHold();piano.Invalidate();meter.Value=Math.Min(100,(int)(Math.Max(Engine.Peak,boxes.Peak)*100));if(audio!=null&&audio.Error!=null){audioStatus.Text="AUDIO OFFLINE";activity.Text=audio.Error;}if(++ticks%200==0&&!HardwareChecks.Skip)RefreshMidi(false);}
    bool mapDirty;
    void UpdateMaps(){for(int i=0;i<8;i++){dials[i].Learning=Router.Learn==i;int m=Router.Maps[i];string next=m<0?"unassigned · click Learn":"CC "+(m%128)+" · channel "+(m/128+1);if(dials[i].Mapping!=next){mapDirty=true;dials[i].Mapping=next;}dials[i].Invalidate();}}
    void LoadMaps(){try{if(File.Exists(settings)){string[] lines=File.ReadAllLines(settings);for(int i=0;i<8&&i<lines.Length;i++){int value;if(int.TryParse(lines[i],out value)&&value>=-1&&value<2048)Router.Maps[i]=value;}}}catch{activity.Text="Could not load knob mappings.";}UpdateMaps();mapDirty=false;}
    void SaveMaps(){if(testing)return;try{string[] lines=new string[8];for(int i=0;i<8;i++)lines[i]=Router.Maps[i].ToString();File.WriteAllLines(settings,lines);}catch{activity.Text="Mappings work now; unable to save in this folder.";}}
    void UpdateHold(){updatingHold=true;holdToggle.Checked=Engine.HoldMode;droneToggle.Checked=Engine.DroneMode;glitchToggle.Checked=Engine.GlitchMode;fragmentsToggle.Checked=Engine.FragmentsMode;updatingHold=false;}
    public void Panic(){takePlayer.Stop();StopSoundFile();Engine.Panic();boxes.Panic();heldKeys.Clear();Router.Learn=-1;UpdateMaps();UpdateHold();activity.Text="Panic: notes, latches and effect tails cleared.";}
    void ToggleStop(){Engine.Stopped=!Engine.Stopped;Panic();stop.Text=Engine.Stopped?"RESUME SOUND":"STOP / RESUME";stop.BackColor=Engine.Stopped?Color.FromArgb(108,52,43):Theme.Card;activity.Text=Engine.Stopped?"Stopped · click Resume to play again.":"Sound resumed.";}
    void ReleaseComputer(){foreach(int note in heldKeys.Values)Engine.NoteOff(note,16);heldKeys.Clear();}
    void KeyPressed(object sender,KeyEventArgs e){if(e.KeyCode==Keys.Escape){Panic();e.SuppressKeyPress=true;return;}if((e.KeyCode==Keys.Z||e.KeyCode==Keys.X)&&!heldKeys.ContainsKey(e.KeyCode)){ReleaseComputer();octave=Math.Max(1,Math.Min(7,octave+(e.KeyCode==Keys.Z?-1:1)));piano.BaseNote=octave*12;piano.Invalidate();e.SuppressKeyPress=true;return;}if(e.Control||e.Alt||presets.DroppedDown||midiChoice.DroppedDown||audioChoice.DroppedDown||glitchTypeChoice.DroppedDown||boxGlitchChoice.DroppedDown||electroChoice.DroppedDown||technologyChoice.DroppedDown||ActiveControl is NumericUpDown)return;for(int i=0;i<noteKeys.Length;i++)if(e.KeyCode==noteKeys[i]){if(!heldKeys.ContainsKey(e.KeyCode)){int note=octave*12+i;heldKeys[e.KeyCode]=note;Engine.NoteOn(note,100,16);}e.SuppressKeyPress=true;return;}}
    void KeyReleased(object sender,KeyEventArgs e){int note;if(heldKeys.TryGetValue(e.KeyCode,out note)){Engine.NoteOff(note,16);heldKeys.Remove(e.KeyCode);e.SuppressKeyPress=true;}}
    void TestComputerKeyboard(){
      if(noteKeys.Length!=25||ComputerKeyboard.Labels.Length!=25||new HashSet<Keys>(noteKeys).Count!=25)throw new Exception("Every displayed note needs a unique keyboard shortcut");
      for(int index=0;index<noteKeys.Length;index++){KeyPressed(this,new KeyEventArgs(noteKeys[index]));if(!Engine.IsNote(piano.BaseNote+index))throw new Exception("Missing computer-key note: "+ComputerKeyboard.Labels[index]);KeyReleased(this,new KeyEventArgs(noteKeys[index]));if(Engine.IsNote(piano.BaseNote+index))throw new Exception("Computer-key note did not release: "+ComputerKeyboard.Labels[index]);}
      KeyPressed(this,new KeyEventArgs(Keys.A));KeyPressed(this,new KeyEventArgs(Keys.D8));if(!Engine.IsNote(48)||!Engine.IsNote(72))throw new Exception("The full two-octave chord should be playable");ReleaseComputer();if(Engine.IsNote(48)||Engine.IsNote(72)||heldKeys.Count!=0)throw new Exception("Losing focus should release the full keyboard range");
      KeyPressed(this,new KeyEventArgs(Keys.D8));KeyPressed(this,new KeyEventArgs(Keys.X));if(Engine.IsNote(72)||piano.BaseNote!=60)throw new Exception("Octave changes should release old computer notes");KeyPressed(this,new KeyEventArgs(Keys.D8));if(!Engine.IsNote(84))throw new Exception("Highest shortcut should follow octave changes");KeyReleased(this,new KeyEventArgs(Keys.D8));KeyPressed(this,new KeyEventArgs(Keys.Z));if(piano.BaseNote!=48)throw new Exception("Octave down should restore the keyboard range");
    }
    void TestPitchControls(string path){
      Engine.NoteOn(60,100,0);slower.PerformClick();if(Engine.PitchSemitones!= -1||!Engine.IsNote(60))throw new Exception("Slower button must retain a held note");faster.PerformClick();if(Engine.PitchSemitones!=0)throw new Exception("Faster button should raise pitch one semitone");for(int index=0;index<15;index++)faster.PerformClick();if(Engine.PitchSemitones!=12||faster.Enabled)throw new Exception("Faster button limit failed");normalSpeed.PerformClick();if(Engine.PitchSemitones!=0||!faster.Enabled||!slower.Enabled)throw new Exception("Normal button reset failed");clarityToggle.Checked=false;if(Engine.NoteClarity)throw new Exception("Key Clarity bypass failed");clarityToggle.Checked=true;if(!Engine.NoteClarity)throw new Exception("Key Clarity enable failed");
      sessionOverride=Path.ChangeExtension(path,"session.txt");try{presets.SelectedIndex=3;dials[0].SetValue(.12,true);echoTimeControl.Value=4000;glitchTypeChoice.SelectedIndex=2;glitchVolumeControl.Value=400;glitchControl.Value=100;fragmentsControl.Value=100;glitchToggle.Checked=fragmentsToggle.Checked=true;volume.Value=30;SetPitch(-7);SaveSession();presets.SelectedIndex=0;SetPitch(9);clarityToggle.Checked=false;LoadSession();if(presets.SelectedIndex!=3||Math.Abs(Engine.Get(0)-.12)>.0001||Engine.EchoTime!=4||!Engine.GlitchMode||!Engine.FragmentsMode||Engine.SelectedGlitchType!=GlitchType.Signals||Engine.GlitchVolume!=4||Engine.GlitchAmount!=1||Engine.FragmentsAmount!=1||volume.Value!=30||Engine.PitchSemitones!= -7||!Engine.NoteClarity||Engine.HoldMode||Engine.DroneMode)throw new Exception("Sound session round-trip failed");}finally{sessionOverride=null;}normalSpeed.PerformClick();Panic();
    }
    public void TestUI(string path){
      presets.SelectedIndex=3;dials[6].SetValue(.63,true);Router.Learn=0;Router.Handle(0xB0|(74<<8)|(95<<16));if(Math.Abs(dials[0].Value-95/127.0)>.001)throw new Exception("UI MIDI learn failed");
      bloomControl.Value=100;echoTimeControl.Value=4000;if(Engine.BloomAmount!=1||Engine.EchoTime!=4)throw new Exception("UI Bloom / Echo Time control failed");
      holdToggle.Checked=true;glitchToggle.Checked=true;fragmentsToggle.Checked=true;glitchControl.Value=100;fragmentsControl.Value=40;if(!Engine.HoldMode||!Engine.GlitchMode||!Engine.FragmentsMode||Engine.GlitchAmount!=1||Engine.FragmentsAmount!=.4)throw new Exception("UI combined effects failed");droneToggle.Checked=true;if(!Engine.DroneMode||!glitchToggle.Checked||!fragmentsToggle.Checked)throw new Exception("Effects should combine with Drone");glitchToggle.Checked=false;if(Engine.GlitchMode||!Engine.FragmentsMode)throw new Exception("Independent effects bypass failed");Panic();if(glitchToggle.Checked||fragmentsToggle.Checked)throw new Exception("Panic should reset effect switches");glitchControl.Value=65;fragmentsControl.Value=65;
      glitchToggle.Checked=true;fragmentsToggle.Checked=true;Engine.NoteOn(57,100,0);for(int type=0;type<glitchTypes.Length;type++){glitchTypeChoice.SelectedIndex=type;if(Engine.SelectedGlitchType!=(GlitchType)type||!Engine.GlitchMode||!Engine.FragmentsMode||!Engine.IsNote(57))throw new Exception("Glitch type selector should retain notes and effects");}glitchVolumeControl.Value=400;if(Engine.GlitchVolume!=4||glitchVolumeValue.Text!="400%"||Engine.GlitchAmount!=.65||!Engine.IsNote(57))throw new Exception("Independent glitch volume UI failed");glitchVolumeControl.Value=0;if(Engine.GlitchVolume!=0||glitchVolumeValue.Text!="0%")throw new Exception("Glitch mute UI failed");Panic();if(glitchTypeChoice.SelectedIndex!=6||Engine.SelectedGlitchType!=GlitchType.Modem||Engine.GlitchVolume!=0)throw new Exception("Panic should preserve the selected glitch type and volume");glitchTypeChoice.SelectedIndex=0;glitchVolumeControl.Value=200;
      TestComputerKeyboard();
      KeyPressed(this,new KeyEventArgs(Keys.A));if(!Engine.IsNote(48))throw new Exception("Computer key failed");KeyReleased(this,new KeyEventArgs(Keys.A));if(Engine.IsNote(48))throw new Exception("Computer key release failed");
      holdToggle.Checked=true;KeyPressed(this,new KeyEventArgs(Keys.A));KeyReleased(this,new KeyEventArgs(Keys.A));if(!Engine.IsNote(48))throw new Exception("UI sustain latch failed");holdToggle.Checked=false;if(Engine.IsNote(48))throw new Exception("UI sustain unlatch failed");
      droneToggle.Checked=true;KeyPressed(this,new KeyEventArgs(Keys.A));KeyReleased(this,new KeyEventArgs(Keys.A));if(!Engine.IsNote(48))throw new Exception("UI drone latch failed");KeyPressed(this,new KeyEventArgs(Keys.A));KeyReleased(this,new KeyEventArgs(Keys.A));if(Engine.IsNote(48))throw new Exception("UI drone note toggle failed");
      presets.SelectedIndex=5;if(!droneToggle.Checked||holdToggle.Checked)throw new Exception("Drone preset should enable drone mode");holdToggle.Checked=true;if(droneToggle.Checked)throw new Exception("Latch mode switching failed");ToggleStop();if(!Engine.Stopped||holdToggle.Checked||droneToggle.Checked)throw new Exception("Stop should clear latches");ToggleStop();if(Engine.Stopped)throw new Exception("Resume failed");droneToggle.Checked=true;Panic();if(holdToggle.Checked||droneToggle.Checked)throw new Exception("Panic should clear latch controls");
      TestPitchControls(path);
      VerifyLayerMixUI();
      Panic();volume.Value=30;for(int i=0;i<8;i++)Router.Maps[i]=-1;UpdateMaps();if(!HardwareChecks.Skip)StartAudio();presets.SelectedIndex=6;using(Bitmap b=new Bitmap(Width,Height)){DrawToBitmap(b,new Rectangle(0,0,Width,Height));b.Save(path,System.Drawing.Imaging.ImageFormat.Png);}
    }
