// Two independent instruments, mixed before the common recorder and audio output.
class SoundBoxes {
    readonly object gate=new object();
    public readonly SoundFilePlayer File=new SoundFilePlayer();
    public readonly Synth Glitch=new Synth(),Electro=new Synth();
    public bool GlitchOn{get;private set;} public bool ElectroOn{get;private set;}
    int electroPatch=12,glitchType=6,glitchNote=60,electroNote=60;
    double master=.2,glitchLevel=.35,electroLevel=.35,glitchGain,electroGain;
    short[] buffer=new short[512]; public volatile float Peak;
    public double Master {set{lock(gate)master=Math.Max(0,Math.Min(.8,value));}}
    public void SetVolume(bool glitch,double value){lock(gate){if(glitch)glitchLevel=Math.Max(0,Math.Min(1,value));else electroLevel=Math.Max(0,Math.Min(1,value));}}
    void Start(bool glitch){Synth synth=glitch?Glitch:Electro;synth.SetPatch(glitch?8:electroPatch);synth.Volume(.8);synth.SetHold(true);if(glitch){synth.SetGlitchType((GlitchType)glitchType);synth.SetGlitch(true);synth.SetGlitchAmount(1);synth.SetGlitchVolume(2);}synth.NoteOn(glitch?glitchNote:electroNote,100,17);synth.NoteOff(glitch?glitchNote:electroNote,17);}
    public void Play(bool glitch,bool on){lock(gate){if(glitch)GlitchOn=on;else ElectroOn=on;if(on)Start(glitch);}}
    public void Retrigger(bool glitch){lock(gate){if(glitch?GlitchOn:ElectroOn)Start(glitch);}}
    public void SetGlitchType(int value){lock(gate){glitchType=Math.Max(0,Math.Min(6,value));Glitch.SetGlitchType((GlitchType)glitchType);}}
    public void SetElectroPatch(int value){lock(gate){value=Math.Max(11,Math.Min(Patch.All.Length-1,value));if(electroPatch==value)return;electroPatch=value;if(ElectroOn)Start(false);}}
    public void SetNote(bool glitch,int value){lock(gate){if(glitch)glitchNote=value;else electroNote=value;if(glitch?GlitchOn:ElectroOn)Start(glitch);}}
    public void Panic(){lock(gate){GlitchOn=ElectroOn=false;glitchGain=electroGain=0;Glitch.Panic();Electro.Panic();Peak=0;}}
    public void FadeOut(double seconds){lock(gate){if(GlitchOn)Glitch.FadeOut(seconds);if(ElectroOn)Electro.FadeOut(seconds);}}
    public void Mix(short[] pcm,int frames){lock(gate){
      if(buffer.Length<frames*2)buffer=new short[frames*2];
      double peak=0;
      for(int part=0;part<2;part++){
        bool glitch=part==0,on=glitch?GlitchOn:ElectroOn;double gain=glitch?glitchGain:electroGain;
        if(!on&&gain==0)continue;
        Synth synth=glitch?Glitch:Electro;synth.Render(buffer,frames);
        double target=on?(glitch?glitchLevel:electroLevel)*master/.8:0;
        for(int frame=0;frame<frames;frame++){gain+=.003*(target-gain);for(int ch=0;ch<2;ch++){int i=frame*2+ch;double sum=pcm[i]+buffer[i]*gain;pcm[i]=(short)Math.Max(-30000,Math.Min(30000,sum));}}
        if(!on&&gain<.000001){gain=0;synth.Panic();}
        if(glitch)glitchGain=gain;else electroGain=gain;
        if(on&&synth.Faded){if(glitch)GlitchOn=false;else ElectroOn=false;}
      }
      File.Mix(pcm,frames,master);for(int i=0;i<frames*2;i++)peak=Math.Max(peak,Math.Abs((double)pcm[i])/30000);Peak=(float)peak;
    }}
    public static void Verify(StringBuilder report){
      SoundBoxes rack=new SoundBoxes();rack.Master=.3;rack.Play(true,true);rack.Play(false,true);short[] pcm=new short[512];double energy=0;
      for(int i=0;i<400;i++){Array.Clear(pcm,0,pcm.Length);rack.Mix(pcm,256);foreach(short sample in pcm)energy+=(double)sample*sample;}
      if(energy==0||!rack.Glitch.IsNote(60)||!rack.Electro.IsNote(60))throw new Exception("Both boxes must sound together");
      rack.SetGlitchType(1);if(!rack.Electro.IsNote(60))throw new Exception("Glitch change reset electro");
      rack.SetElectroPatch(16);if(!rack.Glitch.IsNote(60))throw new Exception("Electro change reset glitch");
      rack.Play(true,false);for(int i=0;i<40;i++){Array.Clear(pcm,0,pcm.Length);rack.Mix(pcm,256);}if(!rack.Electro.IsNote(60)||rack.Peak<=0)throw new Exception("Stopping glitch silenced electro");
      rack.Play(true,true);rack.Play(false,false);for(int i=0;i<40;i++){Array.Clear(pcm,0,pcm.Length);rack.Mix(pcm,256);}if(!rack.Glitch.IsNote(60)||rack.Peak<=0)throw new Exception("Stopping electro silenced glitch");
      rack.Master=0;for(int i=0;i<60;i++){Array.Clear(pcm,0,pcm.Length);rack.Mix(pcm,256);}foreach(short sample in pcm)if(sample!=0)throw new Exception("Master mute failed");
      rack.Master=.3;rack.Play(false,true);rack.FadeOut(1);for(int i=0;i<200;i++){Array.Clear(pcm,0,pcm.Length);rack.Mix(pcm,256);}if(rack.GlitchOn||rack.ElectroOn||rack.Peak!=0)throw new Exception("Both boxes must fade to silence");
      rack.Play(true,true);rack.Play(false,true);rack.Panic();Array.Clear(pcm,0,pcm.Length);rack.Mix(pcm,256);foreach(short sample in pcm)if(sample!=0)throw new Exception("Box panic failed");
      report.AppendLine("PASS: independent Glitch and Old Electro playback, selection, stopping, global mute, fade and Panic");
    }
}

static class Tests {
