    static int Msg(int status,int a,int b){return status|(a<<8)|(b<<16);}
    public static void Run(string dir,bool coreOnly){string reportFile=Path.Combine(dir,coreOnly?"verification-core.txt":"verification.txt");StringBuilder r=new StringBuilder();r.AppendLine("TCKO2 Synth modular prototype 08 verification · "+DateTime.Now.ToString("s"));r.AppendLine("MIDI inputs: "+String.Join(", ",Native.MidiNames()));r.AppendLine("Audio outputs: "+String.Join(", ",Native.AudioNames()));try{
      Check(Marshal.SizeOf(typeof(Native.Header))==(IntPtr.Size==8?48:32),"Native WAVEHDR layout",r);Synth s=new Synth();MidiRouter router=new MidiRouter(s);short[] block=new short[512];
      router.Handle(Msg(0x90,60,100));Check(s.IsNote(60),"MIDI note-on",r);router.Handle(Msg(0x90,60,0));Check(!s.IsNote(60),"Velocity-zero note-off",r);
      router.Handle(Msg(0x91,62,100));router.Handle(Msg(0xB1,64,127));router.Handle(Msg(0x81,62,0));Check(s.IsNote(62),"Channel sustain holds note",r);router.Handle(Msg(0xB1,64,0));Check(!s.IsNote(62),"Sustain releases note",r);
      s.Panic();s.SetHold(true);router.Handle(Msg(0x90,60,100));router.Handle(Msg(0x80,60,0));router.Handle(Msg(0x91,64,100));router.Handle(Msg(0x81,64,0));Check(s.IsNote(60)&&s.IsNote(64),"Sustain latch holds across MIDI channels",r);router.Handle(Msg(0xB1,64,0));Check(s.IsNote(64),"Pedal-off preserves software sustain",r);router.Handle(Msg(0xB0,64,127));s.SetHold(false);Check(s.IsNote(60)&&!s.IsNote(64),"Unlatch respects a still-held MIDI pedal",r);router.Handle(Msg(0xB0,64,0));Check(!s.IsNote(60),"Final pedal-off releases held note",r);
      s.Panic();s.SetPatch(3);s.SetDrone(true);router.Handle(Msg(0x92,57,100));router.Handle(Msg(0x92,57,0));Check(s.IsNote(57),"Drone latches after velocity-zero note-off",r);for(int i=0;i<700;i++)s.Render(block,256);Check(s.IsNote(57)&&s.Peak>.001&&s.InvalidSamples==0,"Drone produces sustained audio after normal release time",r);router.Handle(Msg(0x92,57,100));router.Handle(Msg(0x82,57,0));Check(!s.IsNote(57),"Second drone tap releases without relatching",r);
      s.NoteOn(57,100,2);s.NoteOff(57,2);s.NoteOn(64,100,17);s.NoteOff(64,17);s.ReleaseKeys(17);Check(s.IsNote(64),"Focus loss preserves intentional drone latch",r);s.SetDrone(false);Check(!s.IsNote(57)&&!s.IsNote(64),"Disabling drone releases latched chord",r);
      s.SetDrone(true);s.NoteOn(60,100,0);s.NoteOff(60,0);router.Handle(Msg(0xB0,123,0));Check(!s.IsNote(60),"MIDI all-notes-off clears drone voice",r);s.Panic();Check(!s.HoldMode&&!s.DroneMode,"Panic resets both latch modes",r);s.SetPatch(5);Check(s.DroneMode&&!s.HoldMode,"Dedicated drone preset enables latch",r);s.SetPatch(0);Check(!s.DroneMode&&!s.HoldMode,"Normal preset clears latch modes",r);
      router.Learn=2;router.Handle(Msg(0xB2,71,99));Check(router.Maps[2]==327&&Math.Abs(s.Get(2)-99/127.0)<.0001,"CC learn with channel and value",r);router.Handle(Msg(0xB0,71,10));Check(Math.Abs(s.Get(2)-99/127.0)<.0001,"CC channel isolation",r);
      router.Learn=4;router.Handle(Msg(0xB2,71,20));Check(router.Maps[2]==-1&&router.Maps[4]==327,"Reassignment clears previous mapping",r);
      router.Handle(Msg(0x92,64,127));router.Handle(Msg(0xB2,123,0));Check(!s.IsNote(64),"All notes off",r);s.Panic();s.Render(block,256);bool silent=true;foreach(short v in block)if(v!=0)silent=false;Check(silent,"Panic clears audio and effect tails",r);
      long total=0;double peak=0;Stopwatch sw=Stopwatch.StartNew();using(BinaryWriter w=new BinaryWriter(File.Create(Path.Combine(dir,"preset-preview.wav")))){int seconds=Patch.All.Length*8,bytes=seconds*Synth.Rate*4;w.Write(Encoding.ASCII.GetBytes("RIFF"));w.Write(bytes+36);w.Write(Encoding.ASCII.GetBytes("WAVEfmt "));w.Write(16);w.Write((ushort)1);w.Write((ushort)2);w.Write(Synth.Rate);w.Write(Synth.Rate*4);w.Write((ushort)4);w.Write((ushort)16);w.Write(Encoding.ASCII.GetBytes("data"));w.Write(bytes);
        for(int p=0;p<Patch.All.Length;p++){s.SetPatch(p);s.Volume(.28);double energy=0;int frames=8*Synth.Rate;short[] data=new short[512];for(int frame=0;frame<frames;frame+=256){if(frame==0){s.NoteOn(p==1?36:48,95,0);if(p!=1){s.NoteOn(55,78,0);s.NoteOn(60,85,0);}}if(frame>=Synth.Rate*4&&frame<Synth.Rate*4+256){s.NoteOff(p==1?36:48,0);s.NoteOff(55,0);s.NoteOff(60,0);}int count=Math.Min(256,frames-frame);s.Render(data,count);for(int j=0;j<count*2;j++){w.Write(data[j]);double v=data[j]/32768.0;energy+=v*v;peak=Math.Max(peak,Math.Abs(v));}total+=count;}Check(energy>1,"Non-silent bounded audio: "+Patch.All[p].Name,r);r.AppendLine("  RMS "+Math.Sqrt(energy/(frames*2)).ToString("F4"));}}
      sw.Stop();r.AppendLine("Offline generation: "+total+" stereo frames in "+sw.Elapsed.TotalSeconds.ToString("F2")+"s; peak "+peak.ToString("F4"));Check(peak<.92,"Output headroom",r);
      s.Panic();s.Stopped=true;s.NoteOn(60,100,0);s.Render(block,256);silent=true;foreach(short v in block)if(v!=0)silent=false;Check(silent&&!s.IsNote(60),"Stopped rejects notes and renders silence",r);s.Stopped=false;
      for(int p=0;p<Patch.All.Length;p++){s.SetPatch(p);for(int i=0;i<8;i++)s.Set(i,1);for(int n=0;n<32;n++)s.NoteOn(24+n*3,127,n%16);for(int n=0;n<350;n++){s.Render(block,256);foreach(short v in block)CheckRange(v);}Check(s.ActiveCount<=8&&s.InvalidSamples==0,"Eight-voice limit + finite audio at maximum controls: "+p,r);}s.Panic();
      VerifyExpanse(r);VerifyLongEcho(r);VerifySlices(r);VerifySoundIdentities(r);VerifyGlitchTypes(r);VerifyGlitchVolume(r);VerifyPitchAndClarity(r);VerifyTakeRecording(dir,r);SoundBoxes.Verify(r);
      using(MainForm form=new MainForm(true)){form.Show();Application.DoEvents();form.TestUI(Path.Combine(dir,"TCKO2Synth-preview.png"));Check(true,"UI all 25 keyboard notes, pitch buttons, Key Clarity, session round-trip, octave changes, presets, effects, learn, sustain, drone, stop/resume and panic",r);long before=form.AudioBlocks;Stopwatch wait=Stopwatch.StartNew();while(wait.ElapsedMilliseconds<700){Application.DoEvents();Thread.Sleep(10);}r.AppendLine(form.MidiState);r.AppendLine(form.AudioState);r.AppendLine("Audio blocks: "+form.AudioBlocks+"; error: "+(form.AudioError??"none"));if(coreOnly)r.AppendLine("SKIP: Live Windows audio assertion (--core-test). Native output result above remains unverified or unavailable.");else Check(form.AudioError==null&&form.AudioBlocks>before+10,"Native Windows audio buffers complete and recycle (silent)",r);form.Close();}
      r.AppendLine("Physical key / knob events and audible PC output require a human play check.");r.AppendLine(coreOnly?"RESULT: PASS (DSP/MIDI/UI core checks only; live audio excluded)":"RESULT: PASS");
    }catch(Exception ex){r.AppendLine(ex.ToString());r.AppendLine("RESULT: FAIL");File.WriteAllText(reportFile,r.ToString());throw;}File.WriteAllText(reportFile,r.ToString());}
    static void CheckRange(short v){if(Math.Abs((int)v)>30000)throw new Exception("Audio out of range");}
    static void VerifyTakeRecording(string folder,StringBuilder report){
      Synth synth=new Synth();synth.SetPatch(3);synth.Volume(.3);synth.SetGlitch(true);synth.SetFragments(true);synth.NoteOn(57,100,0);
      string path=Path.Combine(folder,"synth-recording.wav");List<short> expected=new List<short>();short[] block=new short[512];
      using(TCKAudio.PcmRecorder recorder=new TCKAudio.PcmRecorder()){recorder.Start(path);for(int index=0;index<200;index++){synth.Render(block,256);expected.AddRange(block);recorder.Append(block,256);}recorder.Stop();}
      using(BinaryReader reader=new BinaryReader(File.OpenRead(path))){reader.BaseStream.Position=40;Check(reader.ReadUInt32()==expected.Count*2,"Recording WAV length matches every rendered stereo frame",report);foreach(short sample in expected)if(reader.ReadInt16()!=sample)throw new Exception("Recorded PCM differs from synth output");}
      Check(expected.Exists(sample=>sample!=0),"Synth take captures real post-effects audio bit-for-bit",report);
    }
    static Synth PitchTestSynth(int note,int pitch,bool clarity){Synth synth=new Synth();synth.SetPatch(8);for(int control=0;control<8;control++)synth.Set(control,0);synth.SetBloom(0);synth.SetNoteClarity(clarity);synth.SetPitch(pitch);synth.Panic();synth.NoteOn(note,100,0);return synth;}
    static short[] CaptureNote(Synth synth){short[] samples=new short[Synth.Rate*2];synth.Render(samples,Synth.Rate);synth.Render(samples,Synth.Rate);return samples;}
    static double TonePower(short[] samples,double frequency){double coefficient=2*Math.Cos(2*Math.PI*frequency/Synth.Rate),previous=0,older=0;for(int frame=0;frame<samples.Length/2;frame++){double sample=(samples[frame*2]+samples[frame*2+1])/60000.0*(.5-.5*Math.Cos(2*Math.PI*frame/(samples.Length/2-1)));double current=sample+coefficient*previous-older;older=previous;previous=current;}return Math.Max(0,previous*previous+older*older-coefficient*previous*older);}
    static void VerifyPitchAndClarity(StringBuilder report){
      for(int note=24;note<=72;note++){if(note<48&&note%12!=0)continue;short[] samples=CaptureNote(PitchTestSynth(note,0,true));double frequency=220*Math.Pow(2,(note-57)/12.0)/2,center=TonePower(samples,frequency),below=TonePower(samples,frequency*Math.Pow(2,-1/12.0)),above=TonePower(samples,frequency*Math.Pow(2,1/12.0));Check(center>Math.Max(below,above)*3,"Rendered key has its own tuned pitch with Tone zero: MIDI "+note,report);}
      short[] oldTone=CaptureNote(PitchTestSynth(72,0,false)),clearTone=CaptureNote(PitchTestSynth(72,0,true));double gain=TonePower(clearTone,523.251/2)/Math.Max(1e-12,TonePower(oldTone,523.251/2));report.AppendLine("Upper-key fundamental power gain at Tone zero: "+(10*Math.Log10(gain)).ToString("F1")+" dB");Check(gain>10,"Key Clarity restores upper-note pitch instead of closing every key behind an 80 Hz filter",report);
      for(int pitch=-12;pitch<=12;pitch+=12){Synth synth=PitchTestSynth(57,pitch,true);short[] samples=CaptureNote(synth);double frequency=110*Math.Pow(2,pitch/12.0),center=TonePower(samples,frequency),nearby=Math.Max(TonePower(samples,frequency*Math.Pow(2,-1/12.0)),TonePower(samples,frequency*Math.Pow(2,1/12.0)));Check(center>nearby*20,"Tape pitch renders measured frequency "+frequency.ToString("F1")+" Hz at "+pitch+" st",report);synth.SetPitch(-pitch);synth.Render(samples,Synth.Rate);foreach(short sample in samples)CheckRange(sample);Check(synth.IsNote(57)&&synth.InvalidSamples==0,"Pitch changes preserve held note identity: "+pitch,report);synth.NoteOff(57,0);Check(!synth.IsNote(57),"Original note-off works after pitch changes: "+pitch,report);synth.Panic();synth.Render(samples,Synth.Rate);foreach(short sample in samples)if(sample!=0)throw new Exception("Transport retained audio after Panic");}
      Synth fast=PitchTestSynth(57,12,true),slow=PitchTestSynth(57,-12,true);short[] block=new short[512];CaptureNote(fast);CaptureNote(slow);fast.NoteOff(57,0);slow.NoteOff(57,0);for(int frame=0;frame<4096;frame+=256){fast.Render(block,256);slow.Render(block,256);}report.AppendLine("Release peaks at double/half speed: "+fast.Peak.ToString("F6")+" / "+slow.Peak.ToString("F6"));Check(fast.Peak<slow.Peak*.3,"Slower lengthens release and Faster shortens it, not only pitch",report);
      SliceEffects low=new SliceEffects(),high=new SliceEffects();double difference=0;for(int frame=0;frame<Synth.Rate;frame++){double left=.2,right=.2,otherLeft=.2,otherRight=.2;low.Process(ref left,ref right,1,0,GlitchType.Signals,4,110);high.Process(ref otherLeft,ref otherRight,1,0,GlitchType.Signals,4,220);difference+=(left-otherLeft)*(left-otherLeft);}Check(difference>100,"Error-signal glitch pitch follows the played key under Key Clarity",report);
      Synth maximum=PitchTestSynth(48,12,true);maximum.SetPatch(7);maximum.SetGlitch(true);maximum.SetFragments(true);maximum.SetGlitchVolume(4);maximum.SetGlitchAmount(1);maximum.SetFragmentsAmount(1);maximum.SetBloom(1);maximum.SetEchoTime(4);for(int control=0;control<8;control++){maximum.Set(control,1);maximum.NoteOn(48+control,127,0);}Stopwatch stopwatch=Stopwatch.StartNew();for(int blockIndex=0;blockIndex<1750;blockIndex++){maximum.Render(block,256);foreach(short sample in block)CheckRange(sample);}stopwatch.Stop();report.AppendLine("Double-speed eight-voice maximum effects: 10.2s rendered in "+stopwatch.Elapsed.TotalSeconds.ToString("F2")+"s");Check(maximum.InvalidSamples==0&&stopwatch.Elapsed.TotalSeconds<10,"Double-speed combined effects remain bounded and faster than real time",report);maximum.Stopped=true;maximum.Render(block,256);foreach(short sample in block)if(sample!=0)throw new Exception("Stopped transport emitted audio");maximum.SetPitch(99);Check(maximum.PitchSemitones==12,"Pitch clamps to double speed",report);maximum.SetPitch(-99);Check(maximum.PitchSemitones== -12,"Pitch clamps to half speed",report);
    }
    static void VerifyGlitchTypes(StringBuilder report){
      const int frames=88200;int typeCount=Enum.GetValues(typeof(GlitchType)).Length;double[][] outputs=new double[typeCount][];double originalEnergy=0;
      for(int frame=0;frame<frames;frame++){double original=.18*Math.Sin(frame*2*Math.PI*220/Synth.Rate)+.08*Math.Sin(frame*2*Math.PI*1760/Synth.Rate);originalEnergy+=original*original;}
      for(int type=0;type<typeCount;type++){SliceEffects effect=new SliceEffects(),bypass=new SliceEffects(),quiet=new SliceEffects();outputs[type]=new double[frames];double difference=0;
        for(int frame=0;frame<frames;frame++){double original=.18*Math.Sin(frame*2*Math.PI*220/Synth.Rate)+.08*Math.Sin(frame*2*Math.PI*1760/Synth.Rate),left=original,right=original;effect.Process(ref left,ref right,1,0,(GlitchType)type);if(Double.IsNaN(left)||Double.IsInfinity(left)||Math.Abs(left)>1)throw new Exception("Unbounded glitch type output");outputs[type][frame]=left;double change=left-original;difference+=change*change;double cleanLeft=original,cleanRight=original;bypass.Process(ref cleanLeft,ref cleanRight,0,0,(GlitchType)type);if(cleanLeft!=original||cleanRight!=original)throw new Exception("Glitch type bypass changed the input");double silentLeft=0,silentRight=0;quiet.Process(ref silentLeft,ref silentRight,1,1,(GlitchType)type);if(silentLeft!=0||silentRight!=0)throw new Exception("Glitch generated sound without a note");}
        Check(difference>originalEnergy*.005,"Selected glitch type changes sound, bypasses exactly, and respects silence: "+(GlitchType)type,report);
      }
      for(int first=0;first<typeCount;first++)for(int second=first+1;second<typeCount;second++){double difference=0;for(int frame=0;frame<frames;frame++){double change=outputs[first][frame]-outputs[second][frame];difference+=change*change;}Check(difference>originalEnergy*.005,"Different rendered glitch types: "+(GlitchType)first+" / "+(GlitchType)second,report);}
      Synth synth=new Synth();synth.SetPatch(7);synth.SetGlitch(true);synth.SetFragments(true);synth.SetGlitchAmount(1);synth.SetGlitchVolume(4);synth.SetFragmentsAmount(1);synth.SetBloom(1);synth.SetEchoTime(4);for(int control=0;control<8;control++){synth.Set(control,1);synth.NoteOn(48+control,127,0);}short[] pcm=new short[512];
      for(int type=0;type<typeCount;type++){synth.SetGlitchType((GlitchType)type);for(int block=0;block<520;block++){synth.Render(pcm,256);foreach(short sample in pcm)CheckRange(sample);}Check(synth.ActiveCount==8&&synth.FragmentsMode&&synth.InvalidSamples==0,"Live glitch type switch retains eight voices and Fragments at 400%: "+(GlitchType)type,report);synth.Stopped=true;synth.Render(pcm,256);foreach(short sample in pcm)if(sample!=0)throw new Exception("Stopped glitch type emitted audio");synth.Stopped=false;}
      synth.Panic();synth.Render(pcm,256);foreach(short sample in pcm)if(sample!=0)throw new Exception("Glitch type survived Panic");Check(!synth.GlitchMode&&synth.SelectedGlitchType==GlitchType.Modem,"Panic silences artifacts and retains the chosen glitch type",report);synth.SetPatch(0);Check(synth.SelectedGlitchType==GlitchType.Modem,"Preset changes retain the chosen glitch type",report);
    }
    static void VerifyGlitchVolume(StringBuilder report){
      foreach(GlitchType type in Enum.GetValues(typeof(GlitchType))){SliceEffects normal=new SliceEffects(),boosted=new SliceEffects(),muted=new SliceEffects(),bypassed=new SliceEffects();double normalEnergy=0,boostedEnergy=0;
        for(int frame=0;frame<88200;frame++){double original=.18*Math.Sin(frame*2*Math.PI*220/Synth.Rate)+.08*Math.Sin(frame*2*Math.PI*1760/Synth.Rate),normalLeft=original,normalRight=original,boostedLeft=original,boostedRight=original,mutedLeft=original,mutedRight=original,bypassLeft=original,bypassRight=original;normal.Process(ref normalLeft,ref normalRight,1,0,type,1);boosted.Process(ref boostedLeft,ref boostedRight,1,0,type,4);muted.Process(ref mutedLeft,ref mutedRight,1,0,type,0);bypassed.Process(ref bypassLeft,ref bypassRight,0,0,type,4);normalEnergy+=normalLeft*normalLeft;boostedEnergy+=boostedLeft*boostedLeft;if(mutedLeft!=original||mutedRight!=original||bypassLeft!=original||bypassRight!=original)throw new Exception("Glitch volume changed a muted or bypassed dry signal");}
        report.AppendLine("Glitch 400% / 100% RMS: "+type+" = "+Math.Sqrt(boostedEnergy/normalEnergy).ToString("F2"));Check(boostedEnergy>normalEnergy*1.2,"Independent glitch gain audibly increases signal energy; zero and bypass retain dry sound: "+type,report);
      }
      Synth baseline=new Synth(),mutedSynth=new Synth();mutedSynth.SetGlitchVolume(0);mutedSynth.Panic();baseline.SetFragments(true);mutedSynth.SetFragments(true);mutedSynth.SetGlitch(true);mutedSynth.SetGlitchType(GlitchType.Modem);baseline.NoteOn(57,100,0);mutedSynth.NoteOn(57,100,0);short[] expected=new short[512],actual=new short[512];for(int block=0;block<520;block++){baseline.Render(expected,256);mutedSynth.Render(actual,256);for(int sample=0;sample<expected.Length;sample++)if(expected[sample]!=actual[sample])throw new Exception("Muted Glitch affected notes or Fragments");}Check(true,"Glitch volume zero leaves notes and Fragments bit-identical",report);mutedSynth.SetGlitchVolume(8);Check(mutedSynth.GlitchVolume==4,"Glitch gain clamps to 400%",report);mutedSynth.SetGlitchVolume(-1);Check(mutedSynth.GlitchVolume==0,"Glitch gain clamps to mute",report);
    }
    static Synth NeutralSound(int preset){Synth synth=new Synth();synth.SetPatch(preset);synth.SetDrone(false);synth.SetBloom(0);for(int control=0;control<8;control++)synth.Set(control,control==0?.9:control==2?.12:control==7?.4:0);synth.NoteOn(57,100,0);return synth;}
    static double[] SoundSpectrum(int preset){
      Synth synth=NeutralSound(preset);const int count=32768;double[] real=new double[count],imaginary=new double[count],spectrum=new double[32];short[] pcm=new short[512];
      for(int block=0;block<256;block++){synth.Render(pcm,256);if(block<128)continue;for(int sample=0;sample<256;sample++){int index=(block-128)*256+sample;real[index]=(pcm[sample*2]+pcm[sample*2+1])*.5*(.5-.5*Math.Cos(2*Math.PI*index/(count-1)));}}
      for(int index=1,reversed=0;index<count;index++){int bit=count>>1;for(; (reversed&bit)!=0;bit>>=1)reversed^=bit;reversed^=bit;if(index<reversed){double temporary=real[index];real[index]=real[reversed];real[reversed]=temporary;}}
      for(int length=2;length<=count;length<<=1){double step=-2*Math.PI/length;for(int start=0;start<count;start+=length)for(int offset=0;offset<length/2;offset++){int first=start+offset,second=first+length/2;double cosine=Math.Cos(step*offset),sine=Math.Sin(step*offset),rotatedReal=real[second]*cosine-imaginary[second]*sine,rotatedImaginary=real[second]*sine+imaginary[second]*cosine;real[second]=real[first]-rotatedReal;imaginary[second]=imaginary[first]-rotatedImaginary;real[first]+=rotatedReal;imaginary[first]+=rotatedImaginary;}}
      for(int index=1;index<count/2;index++){double frequency=index*(double)Synth.Rate/count;if(frequency<40||frequency>=12000)continue;int band=(int)(Math.Log(frequency/40)/Math.Log(300)*spectrum.Length);spectrum[band]+=real[index]*real[index]+imaginary[index]*imaginary[index];}for(int band=0;band<spectrum.Length;band++)spectrum[band]=Math.Sqrt(spectrum[band]);return spectrum;
    }
    static double SpectralSimilarity(double[] first,double[] second){double dot=0,firstPower=0,secondPower=0;for(int band=0;band<first.Length;band++){dot+=first[band]*second[band];firstPower+=first[band]*first[band];secondPower+=second[band]*second[band];}return dot/Math.Sqrt(firstPower*secondPower);}
    static double AttackDecayRatio(int preset){Synth synth=NeutralSound(preset);short[] pcm=new short[512];double early=0,late=0;int earlyCount=0,lateCount=0;for(int block=0;block<310;block++){synth.Render(pcm,256);for(int sample=0;sample<256;sample++){int frame=block*256+sample;double value=pcm[sample*2]/32768.0;if(frame>=4410&&frame<13230){early+=value*value;earlyCount++;}if(frame>=66150&&frame<74970){late+=value*value;lateCount++;}}}return Math.Sqrt((early/earlyCount)/(late/lateCount));}
    static void VerifySoundIdentities(StringBuilder report){
      double[][] spectra=new double[11][];for(int preset=0;preset<spectra.Length;preset++)spectra[preset]=SoundSpectrum(preset);
      int[,] pairs={{2,3},{0,8},{1,9},{4,6},{5,7},{0,10}};
      for(int pair=0;pair<pairs.GetLength(0);pair++){int first=pairs[pair,0],second=pairs[pair,1];double similarity=SpectralSimilarity(spectra[first],spectra[second]);report.AppendLine("Neutral same-note spectral similarity: "+Patch.All[first].Name+" / "+Patch.All[second].Name+" = "+similarity.ToString("F3"));Check(similarity<.95,"Different sound spectra at identical macro settings: "+first+" / "+second,report);}
      double pianoDecay=AttackDecayRatio(2),organDecay=AttackDecayRatio(8);report.AppendLine("Early/late RMS: electric piano "+pianoDecay.ToString("F2")+", organ "+organDecay.ToString("F2"));Check(pianoDecay>3&&organDecay>.8&&organDecay<1.2,"Electric piano decays while the organ sustains steadily",report);
      double closest=0;int closestFirst=0,closestSecond=0;for(int first=0;first<spectra.Length;first++)for(int second=first+1;second<spectra.Length;second++){double similarity=SpectralSimilarity(spectra[first],spectra[second]);if(similarity>closest){closest=similarity;closestFirst=first;closestSecond=second;}}report.AppendLine("Closest original neutral spectra: "+Patch.All[closestFirst].Name+" / "+Patch.All[closestSecond].Name+" = "+closest.ToString("F3"));Check(closest<.95,"Original preset pairs retain different spectra with the same note and macro settings",report);
    }
    static void VerifySlices(StringBuilder report){
      SliceEffects bypass=new SliceEffects(),fragments=new SliceEffects();double tailEnergy=0;
      for(int frame=0;frame<70000;frame++){double original=frame<40000?.2*Math.Sin(frame*.057):0;double left=original,right=-original;bypass.Process(ref left,ref right,0,0);if(left!=original||right!= -original)throw new Exception("Disabled effects changed the original sound");left=original;right=-original;fragments.Process(ref left,ref right,0,1);if(frame>41000)tailEnergy+=left*left+right*right;}
      Check(true,"Effects bypass preserves samples exactly",report);Check(tailEnergy>1,"Fragments replays captured sound after the input stops",report);fragments.Clear();double clearedLeft=0,clearedRight=0;fragments.Process(ref clearedLeft,ref clearedRight,1,1);Check(clearedLeft==0&&clearedRight==0,"Clearing slice history removes captured audio",report);
      for(int mode=0;mode<3;mode++){Synth dry=new Synth(),wet=new Synth();wet.SetGlitch(mode!=1);wet.SetFragments(mode!=0);dry.SetHold(true);wet.SetHold(true);dry.NoteOn(57,100,0);wet.NoteOn(57,100,0);short[] clean=new short[512],processed=new short[512];double energy=0,difference=0;for(int block=0;block<520;block++){dry.Render(clean,256);wet.Render(processed,256);for(int sample=0;sample<processed.Length;sample++){CheckRange(processed[sample]);energy+=(double)clean[sample]*clean[sample];double change=processed[sample]-clean[sample];difference+=change*change;}}Check(difference>energy*.02&&wet.InvalidSamples==0,(mode==0?"Glitch":mode==1?"Fragments":"Combined effects")+" changes live sustained sound with bounded output",report);wet.Panic();wet.Render(processed,256);bool silent=true;foreach(short sample in processed)if(sample!=0)silent=false;Check(silent&&!wet.GlitchMode&&!wet.FragmentsMode,"Panic clears slice audio and switches: "+mode,report);}
      Synth maximum=new Synth();maximum.SetPatch(7);maximum.SetBloom(1);maximum.SetEchoTime(4);maximum.SetGlitch(true);maximum.SetFragments(true);maximum.SetGlitchAmount(1);maximum.SetFragmentsAmount(1);maximum.Volume(.8);for(int control=0;control<8;control++){maximum.Set(control,1);maximum.NoteOn(48+control,127,0);}short[] pcm=new short[512];Stopwatch stopwatch=Stopwatch.StartNew();for(int block=0;block<3500;block++){maximum.Render(pcm,256);foreach(short sample in pcm)CheckRange(sample);}stopwatch.Stop();report.AppendLine("Maximum eight-voice Glitch + Fragments + Bloom + echo: 20.3s in "+stopwatch.Elapsed.TotalSeconds.ToString("F2")+"s.");Check(maximum.InvalidSamples==0&&stopwatch.Elapsed.TotalSeconds<20,"Combined slice effects remain stable and render faster than real time",report);maximum.Stopped=true;maximum.Render(pcm,256);bool stoppedSilent=true;foreach(short sample in pcm)if(sample!=0)stoppedSilent=false;Check(stoppedSilent,"Stop silences combined effects",report);maximum.SetGlitchAmount(2);maximum.SetFragmentsAmount(-1);Check(maximum.GlitchAmount==1&&maximum.FragmentsAmount==0,"Effect strength clamps to its usable range",report);maximum.SetPatch(0);Check(!maximum.GlitchMode&&!maximum.FragmentsMode,"Preset changes clear slice switches and history",report);
    }
    static double StereoCorrelation(Synth s){short[] pcm=new short[512];double ll=0,rr=0,lr=0;for(int i=0;i<690;i++){s.Render(pcm,256);if(i<345)continue;for(int j=0;j<512;j+=2){double l=pcm[j],r=pcm[j+1];ll+=l*l;rr+=r*r;lr+=l*r;}}return lr/Math.Sqrt(ll*rr);}
    static Synth BloomTestSynth(double bloom){Synth s=new Synth();s.SetPatch(3);for(int i=0;i<8;i++)s.Set(i,0);s.Set(0,.7);s.SetBloom(bloom);s.SetHold(true);s.NoteOn(57,100,0);s.NoteOff(57,0);return s;}
    static void VerifyExpanse(StringBuilder r){Synth dry=BloomTestSynth(0),wide=BloomTestSynth(1);double dryCorrelation=StereoCorrelation(dry),wideCorrelation=StereoCorrelation(wide);r.AppendLine("Stereo correlation: dry "+dryCorrelation.ToString("F4")+", Bloom "+wideCorrelation.ToString("F4"));Check(wideCorrelation<dryCorrelation-.01,"Bloom adds stereo spread to sustained notes",r);wide.SetHold(false);short[] pcm=new short[512];for(int i=0;i<520;i++)wide.Render(pcm,256);Check(wide.ActiveCount>0&&wide.Peak>.001,"Bloom gives held notes a long natural release",r);wide.Panic();wide.Render(pcm,256);bool silent=true;foreach(short v in pcm)if(v!=0)silent=false;Check(silent,"Panic clears expanded chorus and long effect tails",r);
      Synth maximum=new Synth();maximum.SetPatch(7);maximum.SetBloom(1);maximum.SetEchoTime(4);maximum.Volume(.8);for(int i=0;i<8;i++){maximum.Set(i,1);maximum.NoteOn(48+i,127,0);}Stopwatch sw=Stopwatch.StartNew();for(int i=0;i<3500;i++){maximum.Render(pcm,256);foreach(short v in pcm)CheckRange(v);}sw.Stop();r.AppendLine("Maximum 8-voice Bloom + 4s echo: 20.3s rendered in "+sw.Elapsed.TotalSeconds.ToString("F2")+"s.");Check(maximum.InvalidSamples==0&&maximum.ActiveCount==8,"Long feedback stability at maximum Bloom, echo and reverb",r);Check(sw.Elapsed.TotalSeconds<20,"Expanded engine renders faster than real time",r);
    }
    static void VerifyLongEcho(StringBuilder r){Synth s=new Synth();s.SetPatch(1);for(int i=0;i<8;i++)s.Set(i,0);s.Set(0,.7);s.Set(4,1);s.SetBloom(0);s.SetEchoTime(1.25);short[] pcm=new short[512];for(int i=0;i<350;i++)s.Render(pcm,256);s.NoteOn(69,100,0);double early=0,first=0,late=0;for(int frame=0;frame<5*Synth.Rate;frame+=256){if(frame>=Synth.Rate*.1&&frame<Synth.Rate*.1+256)s.NoteOff(69,0);s.Render(pcm,256);double t=frame/(double)Synth.Rate;double energy=0;foreach(short v in pcm){double x=v/32768.0;energy+=x*x;}if(t>.7&&t<.95)early+=energy;if(t>1.22&&t<1.55)first+=energy;if(t>3.72&&t<3.99)late+=energy;}r.AppendLine("Echo window energy: before repeat "+early.ToString("F6")+", first "+first.ToString("F6")+", third "+late.ToString("F6"));Check(first>.01&&first>early*10,"Echo Time delays the first repeat beyond one second",r);Check(late>.001&&s.InvalidSamples==0,"Echo repeats persist several seconds after a short note",r);s.SetEchoTime(99);Check(s.EchoTime==4,"Echo Time supports four seconds and clamps upper range",r);s.SetEchoTime(-1);Check(s.EchoTime==.08,"Echo Time retains a short slapback setting",r);}
}
static class Program {
    [STAThread] static void Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{HardwareChecks.Skip=args.Length>0&&(args[0]=="--core-test"||args[0]=="--files-test"||args[0]=="--technologies-test"||args[0]=="--layers-test");if(args.Length>=2&&args[0]=="--layers-test"){LayerMixChecks.Run(args[1]);return;}if(args.Length>=2&&args[0]=="--technologies-test"){TechnologyChecks.Run(args[1]);return;}if(args.Length>=2&&args[0]=="--files-test"){SoundFileChecks.Run(args[1]);return;}if(args.Length>0&&(args[0]=="--self-test"||args[0]=="--core-test")){Tests.Run(args.Length>1?args[1]:AppDomain.CurrentDomain.BaseDirectory,args[0]=="--core-test");return;}Application.Run(new MainForm(false));}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"last-error.txt"),ex.ToString());if(args.Length==0)MessageBox.Show(ex.Message,"TCKO2 Synth modular",MessageBoxButtons.OK,MessageBoxIcon.Error);Environment.ExitCode=1;}}
